import {ContractError} from './cloud-contract.mjs';
const uuid=v=>typeof v==='string'&&/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/i.test(v);
export function personalSettingsState(v){if(!v||!v.account||!uuid(v.account.id)||typeof v.account.username!=='string'||!['admin','employee'].includes(v.account.role)||!Number.isSafeInteger(v.account.version)||v.account.version<1||v.passwordChangeSupported!==true||typeof v.canMaintainMember!=='boolean'||v.profile!==null&&(!v.profile||!uuid(v.profile.id)||typeof v.profile.displayName!=='string'))throw new ContractError('个人资料暂不完整，请刷新后重试。');return v;}
export function personalPasswordPayload(v){if(!v||Object.keys(v).some(k=>!['requestKey','expectedVersion','currentPassword','newPassword'].includes(k))||!uuid(v.requestKey)||!Number.isSafeInteger(v.expectedVersion)||v.expectedVersion<1||typeof v.currentPassword!=='string'||!v.currentPassword.length||v.currentPassword.length>128||typeof v.newPassword!=='string'||v.newPassword.length<12||v.newPassword.length>128||!v.newPassword.trim()||v.newPassword===v.currentPassword)throw new ContractError('请填写当前密码，并设置不同的12至128个字符的新密码。');return v;}
export function personalPasswordResult(v){if(v?.ok!==true||v.signedOut!==true)throw new ContractError('改密结果未确认，请重新登录核对。');return v;}
export function createPersonalSettingsView({api,h,heading,facts,writable,onSignedOut}){
 async function render(container,oldProfile,user,signal){let state;try{state=await api.personalSettings(signal);}catch(e){if(e.status!==404)throw e;}if(signal.aborted)return;const profile=state?.profile??(state?null:oldProfile),account=state?.account??user;
  container.innerHTML=heading('个人资料','查看自己的成员资料与登录设置。')+`<section class="work-panel planning-panel"><h2>成员资料</h2>${facts([['成员姓名',profile?.displayName||profile?.display_name||'尚未关联成员'],['岗位',profile?.jobTitle||profile?.job_title],['入职日期',profile?.startDate||profile?.start_date],['最后在职日（含当天）',profile?.endDate||profile?.end_date],['在职状态',profile?.employmentStatus||profile?.employment_status]])}<p class="muted">姓名、岗位、任职日期和在职状态由人员管理员统一维护。${profile?'如需更正，请联系人员管理员。':'当前账号尚未关联成员，请联系管理员核对；不会自动关联其他成员。'}</p>${state?.canMaintainMember?'<a class="secondary" href="#members">前往团队成员维护</a>':''}</section><section class="work-panel planning-panel"><h2>登录设置</h2>${facts([['登录用户名',account.username],['角色',account.role==='admin'?'管理员':'员工']])}<p class="muted">登录用户名用于固定识别账号；角色、权限和成员关联由账号管理员维护。本人可验证当前密码后修改自己的密码。</p>${writable&&state?`<form id="personal-password-form"><label>当前密码<input name="currentPassword" type="password" autocomplete="current-password" required maxlength="128"></label><label>新密码<input name="newPassword" type="password" autocomplete="new-password" required minlength="12" maxlength="128"></label><label>再次输入新密码<input name="confirmation" type="password" autocomplete="new-password" required minlength="12" maxlength="128"></label><p class="muted">密码为12至128个字符。修改成功后，所有设备上的旧登录都会退出，请用新密码重新登录。</p><p class="save-error" role="alert" aria-live="polite"></p><button class="primary" type="submit">修改密码并退出登录</button></form>`:`<p class="muted">${writable?'当前服务尚未开放本人修改密码，请联系管理员。':'当前为只读预览，无法修改密码。'}</p>`}</section>`;
  const form=container.querySelector('#personal-password-form');if(!form)return;let busy=false,stale=false;const button=form.querySelector('button'),error=form.querySelector('[role=alert]'),clear=()=>form.reset();signal.addEventListener('abort',clear,{once:true});
  form.onsubmit=async e=>{e.preventDefault();if(busy||stale)return;error.textContent='';const values=new FormData(form);if(values.get('newPassword')!==values.get('confirmation')){clear();error.textContent='两次新密码不一致，请重新填写。';return;}let data;try{data=personalPasswordPayload({requestKey:crypto.randomUUID(),expectedVersion:state.account.version,currentPassword:values.get('currentPassword'),newPassword:values.get('newPassword')});}catch(e){clear();error.textContent=e.message;return;}busy=true;button.disabled=true;button.textContent='正在修改…';form.querySelectorAll('input').forEach(el=>el.disabled=true);try{await api.changeOwnPassword(data);clear();await onSignedOut('changed');}catch(e){clear();if(e.uncertain||e.status===401){await onSignedOut(e.uncertain?'uncertain':'expired');}else if(!signal.aborted){stale=e.status===409;error.textContent=stale?'账号信息已变化，请点击上方“刷新数据”后重新填写。':e.status===400?'当前密码不正确，或新密码不符合要求，请重新核对。':e.status===429?'尝试次数较多，请稍后再试。':e.message;}}finally{data=null;busy=false;button.disabled=stale;button.textContent='修改密码并退出登录';form.querySelectorAll('input').forEach(el=>el.disabled=stale);}};
 }return {render};
}
